1	import { renderHook, act, waitFor } from '@testing-library/react';
2	import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
3	import { AuthProvider, useAuth } from './useAuth';
4	import { supabase } from '@/integrations/supabase/client';
5	import React from 'react';
6	
7	// Mocks do Supabase e window.localStorage
8	vi.mock('@/integrations/supabase/client', () => {
9	  return {
10	    supabase: {
11	      from: vi.fn(),
12	      auth: {
13	        getUser: vi.fn(),
14	        getSession: vi.fn(),
15	        onAuthStateChange: vi.fn(),
16	        signInWithPassword: vi.fn(),
17	        signOut: vi.fn(),
18	        refreshSession: vi.fn(),
19	      },
20	    },
21	  };
22	});
23	
24	// Setup mock do local storage para checar chamadas de cache
25	const localStorageMock = (function () {
26	  let store: Record<string, string> = {};
27	  return {
28	    getItem(key: string) {
29	      return store[key] || null;
30	    },
31	    setItem(key: string, value: string) {
32	      store[key] = value.toString();
33	    },
34	    removeItem(key: string) {
35	      delete store[key];
36	    },
37	    clear() {
38	      store = {};
39	    },
40	  };
41	})();
42	Object.defineProperty(window, 'localStorage', { value: localStorageMock });
43	
44	describe('useAuth e AuthProvider', () => {
45	  const mockUser = { id: 'user-123', email: 'test@example.com' };
46	  const mockSession = {
47	    user: mockUser,
48	    access_token: 'valid-token',
49	    expires_at: Date.now() / 1000 + 3600,
50	  };
51	  const mockProfile = {
52	    id: 'prof-1',
53	    user_id: 'user-123',
54	    nome: 'Test Name',
55	    username: 'testuser',
56	    ativo: true,
57	    role_id: 1,
58	    approved: true,
59	    needs_approval: false,
60	    default_store_id: 1,
61	    can_change_store: true,
62	    created_at: new Date().toISOString(),
63	    updated_at: new Date().toISOString(),
64	  };
65	
66	  beforeEach(() => {
67	    vi.clearAllMocks();
68	    window.localStorage.clear();
69	
70	    // Base setup sem auth listener callback mock
71	    (supabase.auth.onAuthStateChange as any).mockReturnValue({
72	      data: { subscription: { unsubscribe: vi.fn() } },
73	    });
74	  });
75	
76	  const wrapper = ({ children }: { children: React.ReactNode }) => (
77	    <AuthProvider>{children}</AuthProvider>
78	  );
79	
80	  describe('Inicialização e getSession', () => {
81	    it('deve iniciar zerado e definir loading=false se não não houver sessão', async () => {
82	      (supabase.auth.getSession as any).mockResolvedValue({
83	        data: { session: null },
84	        error: null,
85	      });
86	
87	      const { result } = renderHook(() => useAuth(), { wrapper });
88	
89	      await waitFor(() => {
90	        expect(result.current.loading).toBe(false);
91	      });
92	      expect(result.current.user).toBeNull();
93	      expect(result.current.session).toBeNull();
94	      expect(result.current.userProfile).toBeNull();
95	    });
96	
97	    it('deve buscar os dados e popular perfil quando há uma sessão já estabelecida', async () => {
98	      // Mock da sessão inicial
99	      (supabase.auth.getSession as any).mockResolvedValue({
100	        data: { session: mockSession },
101	        error: null,
102	      });
103	
104	      // Mock da requisição 'from' para tabela profiles - eq.maybeSingle
105	      const mockMaybeSingle = vi
106	        .fn()
107	        .mockResolvedValue({ data: mockProfile, error: null });
108	      const mockEq = vi.fn().mockReturnValue({ maybeSingle: mockMaybeSingle });
109	      const mockSelect = vi.fn().mockReturnValue({ eq: mockEq });
110	      (supabase.from as any).mockReturnValue({ select: mockSelect });
111	
112	      const { result } = renderHook(() => useAuth(), { wrapper });
113	
114	      await waitFor(() => {
115	        expect(result.current.loading).toBe(false);
116	      });
117	
118	      await waitFor(() => {
119	        expect(result.current.userProfile).toEqual(mockProfile);
120	      });
121	
122	      expect(result.current.user).toEqual(mockUser);
123	      expect(result.current.needsApproval).toBe(false);
124	      expect(supabase.from).toHaveBeenCalledWith('profiles');
125	      expect(mockEq).toHaveBeenCalledWith('user_id', mockUser.id);
126	      expect(mockMaybeSingle).toHaveBeenCalled();
127	    });
128	
129	    it('deve falhar de forma suave (fallback profile) se o DB retornar null no perfil', async () => {
130	      // Sessão válida
131	      (supabase.auth.getSession as any).mockResolvedValue({
132	        data: { session: mockSession },
133	        error: null,
134	      });
135	
136	      // DB Retornando profile null mas req. de get getUser (para defaults) falhando e fallback ativando
137	      const mockMaybeSingle = vi
138	        .fn()
139	        .mockResolvedValue({ data: null, error: new Error('Fake DB Drop') });
140	      const mockEq = vi.fn().mockReturnValue({ maybeSingle: mockMaybeSingle });
141	      const mockSelect = vi.fn().mockReturnValue({ eq: mockEq });
142	      (supabase.from as any).mockReturnValue({ select: mockSelect });
143	
144	      const { result } = renderHook(() => useAuth(), { wrapper });
145	
146	      await waitFor(() => {
147	        expect(result.current.loading).toBe(false);
148	      });
149	
150	      await waitFor(() => {
151	        expect(result.current.userProfile).not.toBeNull();
152	      });
153	
154	      // O fallback coloca id 'fallback_user-123'
155	      expect(result.current.userProfile?.id).toBe('fallback_user-123');
156	      expect(result.current.userProfile?.approved).toBe(true);
157	    });
158	  });
159	
160	  describe('Métodos de signIn e signOut', () => {
161	    it('deve invocar signInWithPassword com email e senha e setar o loading', async () => {
162	      (supabase.auth.getSession as any).mockResolvedValue({
163	        data: { session: null },
164	      });
165	      const mockSignInResponse = { user: mockUser };
166	      (supabase.auth.signInWithPassword as any).mockResolvedValue({
167	        data: mockSignInResponse,
168	        error: null,
169	      });
170	
171	      const { result } = renderHook(() => useAuth(), { wrapper });
172	
173	      // O Componente em si não define 'user' e 'userProfile' dentro do próprio signOut, e sim no onAuthStateChange que no real test emitiria SIGNED_IN
174	      // Mas podemos atestar as chamadas no auth:
175	      let actionRes;
176	      await act(async () => {
177	        actionRes = await result.current.signIn('test@mail.com', 'pwd123');
178	      });
179	
180	      expect(supabase.auth.signInWithPassword).toHaveBeenCalledWith({
181	        email: 'test@mail.com',
182	        password: 'pwd123',
183	      });
184	      expect(actionRes?.data).toEqual(mockSignInResponse);
185	      expect(actionRes?.error).toBeNull();
186	    });
187	
188	    it('deve invocar auth.signOut e limpar caches (storage)', async () => {
189	      (supabase.auth.getSession as any).mockResolvedValue({
190	        data: { session: mockSession },
191	        error: null,
192	      });
193	      const mockMaybeSingle = vi
194	        .fn()
195	        .mockResolvedValue({ data: mockProfile, error: null });
196	      const mockEq = vi.fn().mockReturnValue({ maybeSingle: mockMaybeSingle });
197	      const mockSelect = vi.fn().mockReturnValue({ eq: mockEq });
198	      (supabase.from as any).mockReturnValue({ select: mockSelect });
199	
200	      const { result } = renderHook(() => useAuth(), { wrapper });
201	
202	      await waitFor(() => {
203	        expect(result.current.userProfile).toBeTruthy();
204	      });
205	
206	      // Mock do Storage contendo resíduos
207	      window.localStorage.setItem(
208	        'userProfile_user-123',
209	        JSON.stringify({ profile: mockProfile, timestamp: Date.now() }),
210	      );
211	
212	      (supabase.auth.signOut as any).mockResolvedValue({ error: null });
213	
214	      await act(async () => {
215	        await result.current.signOut();
216	      });
217	
218	      expect(supabase.auth.signOut).toHaveBeenCalled();
219	      expect(window.localStorage.getItem('userProfile_user-123')).toBeNull();
220	    });
221	  });
222	
223	  describe('Erros de Provider', () => {
224	    it('deve lançar erro se useAuth for invocado fora do AuthProvider', () => {
225	      // Redireciona o console.error temporariamente pois o React quebra propositalmente quando usamos hooks that throw without error boundary
226	      const originalError = console.error;
227	      console.error = vi.fn();
228	
229	      expect(() => renderHook(() => useAuth())).toThrowError(
230	        'useAuth must be used within an AuthProvider',
231	      );
232	
233	      console.error = originalError;
234	    });
235	  });
236	});
