1	import { render, screen } from '@testing-library/react';
2	import { describe, it, expect, vi } from 'vitest';
3	import { PermissionBlur } from './PermissionBlur';
4	import { BrowserRouter } from 'react-router-dom';
5	
6	// Simula os hooks usados dentro do PermissionBlur
7	vi.mock('@/shared/hooks/use-mobile', () => ({
8	  useIsMobile: vi.fn(),
9	}));
10	
11	describe('PermissionBlur', () => {
12	  const renderWithRouter = (ui: React.ReactElement) => {
13	    return render(<BrowserRouter>{ui}</BrowserRouter>);
14	  };
15	
16	  it('renderiza os filhos normalmente quando possui permissão', () => {
17	    renderWithRouter(
18	      <PermissionBlur hasPermission={true}>
19	        <div data-testid="conteudo">Conteúdo Secreto</div>
20	      </PermissionBlur>,
21	    );
22	
