62	        screen_height: window.innerHeight,
63	        device_type: getDeviceType(),
64	        ...extra,
65	      },
66	    }).then(() => {}, () => {}); // Silent - never break UX
67	  }, [user, location.pathname, ensureSession]);
68	
69	  // Track page views on route change
70	  useEffect(() => {
71	    if (!user || location.pathname === lastRouteRef.current) return;
72	    lastRouteRef.current = location.pathname;
