74	
75	    // Update session current_route
76	    if (sessionIdRef.current) {
77	      (supabase as any).from('user_sessions')
78	        .update({ current_route: location.pathname, last_activity: new Date().toISOString() })
79	        .eq('id', sessionIdRef.current)
