111	      if (sessionIdRef.current) {
112	        // Use sendBeacon for reliable delivery on page close
113	        const url = `${import.meta.env.VITE_SUPABASE_URL}/rest/v1/user_sessions?id=eq.${sessionIdRef.current}`;
114	        const payload = JSON.stringify({
115	          is_online: false,
116	          ended_at: new Date().toISOString(),
117	          last_activity: new Date().toISOString(),
118	        });
119	        const headers = {
