126	        const blob = new Blob([payload], { type: 'application/json' });
127	        try {
128	          // Try fetch with keepalive first (supports custom headers)
129	          fetch(url, {
130	            method: 'PATCH',
131	            headers,
132	            body: payload,
133	            keepalive: true,
134	          }).catch(() => {});
135	        } catch {
