146	  // Track JS errors
147	  useEffect(() => {
148	    const handleError = (event: ErrorEvent) => {
149	      logEvent('error', {
150	        error_message: event.message,
151	        error_source: event.filename,
152	        error_line: event.lineno,
153	        error_col: event.colno,
154	      });
155	    };
156	
157	    window.addEventListener('error', handleError);
158	    return () => window.removeEventListener('error', handleError);
159	  }, [logEvent]);
160	
161	  // Click tracking via data-track attribute
162	  useEffect(() => {
163	    if (!user) return;
164	
165	    const handleClick = (event: MouseEvent) => {
166	      const target = event.target as HTMLElement;
167	      const tracked = target.closest('[data-track]') as HTMLElement | null;
168	      if (tracked) {
