170	        logEvent('click', {
171	          element_id: trackId,
172	          element_tag: tracked.tagName.toLowerCase(),
173	          element_text: tracked.textContent?.slice(0, 100) || '',
174	        });
175	      }
176	    };
177	
178	    document.addEventListener('click', handleClick, { capture: true });
179	    return () => document.removeEventListener('click', handleClick, { capture: true });
180	  }, [user, logEvent]);
181	
182	  // Logout tracking: detect user -> null transition
183	  useEffect(() => {
184	    if (prevUserRef.current && !user) {
185	      // User was logged in and is now null => logout
186	      if (sessionIdRef.current) {
187	        (supabase as any).from('user_activity_log').insert({
188	          user_id: prevUserRef.current,
189	          event_type: 'logout',
190	          page_route: location.pathname,
191	          session_id: sessionIdRef.current,
192	          metadata: { device_type: getDeviceType() },
193	        }).then(() => {}, () => {});
194	      }
195	    }
196	    prevUserRef.current = user?.id || null;
197	  }, [user?.id, location.pathname]);
198	
199	  return { logEvent }; // Expose for manual tracking if needed
200	}
